import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    if start is not None:
        init = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        init = np.array([[x, y, 0.02] for x, y in pts])

    z0 = np.concatenate([init[:, 0], init[:, 1], init[:, 2]])

    def unpack(z):
        return z[:n], z[n:2 * n], z[2 * n:]

    def objective(z):
        return -np.sum(z[2 * n:])

    def objective_grad(z):
        g = np.zeros_like(z)
        g[2 * n:] = -1.0
        return g

    def constraints(z):
        x, y, r = unpack(z)
        cons = []
        cons.append(x - r)
        cons.append(1.0 - x - r)
        cons.append(y - r)
        cons.append(1.0 - y - r)
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        rr = r[:, None] + r[None, :]
        d2 = dx * dx + dy * dy - rr * rr
        iu = np.triu_indices(n, k=1)
        cons.append(d2[iu])
        return np.concatenate(cons)

    def constraints_jac(z):
        x, y, r = unpack(z)
        m_wall = 4 * n
        m_pair = n * (n - 1) // 2
        J = np.zeros((m_wall + m_pair, 3 * n))
        idx = 0
        for i in range(n):
            J[idx, i] = 1.0; J[idx, 2 * n + i] = -1.0; idx += 1
        for i in range(n):
            J[idx, i] = -1.0; J[idx, 2 * n + i] = -1.0; idx += 1
        for i in range(n):
            J[idx, n + i] = 1.0; J[idx, 2 * n + i] = -1.0; idx += 1
        for i in range(n):
            J[idx, n + i] = -1.0; J[idx, 2 * n + i] = -1.0; idx += 1
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i] - x[j]; dy = y[i] - y[j]; rr = r[i] + r[j]
                J[idx, i] = 2.0 * dx; J[idx, j] = -2.0 * dx
                J[idx, n + i] = 2.0 * dy; J[idx, n + j] = -2.0 * dy
                J[idx, 2 * n + i] = -2.0 * rr; J[idx, 2 * n + j] = -2.0 * rr
                idx += 1
        return J

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n
    cons_ineq = {'type': 'ineq', 'fun': constraints, 'jac': constraints_jac}

    deadline = t0 + budget_seconds - 0.5

    # Identify active contacts from the start configuration.
    x0, y0, r0 = unpack(z0)
    tol = 1e-4
    active_pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x0[i] - x0[j], y0[i] - y0[j])
            if d - (r0[i] + r0[j]) < tol:
                active_pairs.append((i, j))
    active_walls = []  # (kind, i) kind in 0:x-,1:x+,2:y-,3:y+
    for i in range(n):
        if x0[i] - r0[i] < tol: active_walls.append((0, i))
        if 1.0 - x0[i] - r0[i] < tol: active_walls.append((1, i))
        if y0[i] - r0[i] < tol: active_walls.append((2, i))
        if 1.0 - y0[i] - r0[i] < tol: active_walls.append((3, i))

    def eq_constraints(z):
        x, y, r = unpack(z)
        out = []
        for (i, j) in active_pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]; rr = r[i] + r[j]
            out.append(dx * dx + dy * dy - rr * rr)
        for (kind, i) in active_walls:
            if kind == 0: out.append(x[i] - r[i])
            elif kind == 1: out.append(1.0 - x[i] - r[i])
            elif kind == 2: out.append(y[i] - r[i])
            else: out.append(1.0 - y[i] - r[i])
        return np.array(out)

    def eq_jac(z):
        x, y, r = unpack(z)
        m = len(active_pairs) + len(active_walls)
        J = np.zeros((m, 3 * n))
        idx = 0
        for (i, j) in active_pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]; rr = r[i] + r[j]
            J[idx, i] = 2.0 * dx; J[idx, j] = -2.0 * dx
            J[idx, n + i] = 2.0 * dy; J[idx, n + j] = -2.0 * dy
            J[idx, 2 * n + i] = -2.0 * rr; J[idx, 2 * n + j] = -2.0 * rr
            idx += 1
        for (kind, i) in active_walls:
            if kind == 0:
                J[idx, i] = 1.0; J[idx, 2 * n + i] = -1.0
            elif kind == 1:
                J[idx, i] = -1.0; J[idx, 2 * n + i] = -1.0
            elif kind == 2:
                J[idx, n + i] = 1.0; J[idx, 2 * n + i] = -1.0
            else:
                J[idx, n + i] = -1.0; J[idx, 2 * n + i] = -1.0
            idx += 1
        return J

    z = z0
    try:
        cons_list = [cons_ineq]
        if len(active_pairs) + len(active_walls) > 0:
            cons_list.append({'type': 'eq', 'fun': eq_constraints, 'jac': eq_jac})
        res = minimize(
            objective, z0, jac=objective_grad,
            method='SLSQP', bounds=bounds, constraints=cons_list,
            options={'maxiter': 2000, 'ftol': 1e-12},
        )
        if res.x is not None and np.all(np.isfinite(res.x)):
            # Verify inequality feasibility
            cval = constraints(res.x)
            if np.min(cval) > -1e-7 and np.sum(res.x[2 * n:]) >= np.sum(z0[2 * n:]) - 1e-9:
                z = res.x
    except Exception:
        z = z0

    x, y, r = unpack(z)
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)

    return np.column_stack([x, y, r])
